        "xplr {}\n{}\nA hackable, minimal, fast TUI file explorer\n\nUSAGE:\n    xplr [FLAG]... [OPTION]... [PATH] [SELECTION]...\n\nFLAGS:\n  -                            Reads new-line (\\n) separated paths from stdin\n  --                           Denotes the end of command-line flags and options\n      --force-focus            Focuses on the given <PATH>, even if it is a directory\n  -h, --help                   Prints help information\n  -m, --pipe-msg-in            Helps safely passing messages to the active xplr\n                                 session, use %%, %s and %q as the placeholders\n  -M, --print-msg-in           Like --pipe-msg-in, but prints the message instead of\n                                 passing to the active xplr session\n      --print-pwd-as-result    Prints the present working directory when quitting\n                                 with `PrintResultAndQuit`\n      --read-only              Enables read-only mode (config.general.read_only)\n      --read0                  Reads paths separated using the null character (\\0)\n      --write0                 Prints paths separated using the null character (\\0)\n  -0  --null                   Combines --read0 and --write0\n  -V, --version                Prints version information\n\nOPTIONS:\n  -c, --config <PATH>             Specifies a custom config file (default is\n                                    \"$HOME/.config/xplr/init.lua\")\n  -C, --extra-config <PATH>...    Specifies extra config files to load\n      --on-load <MESSAGE>...      Sends messages when xplr loads\n      --vroot <PATH>              Treats the specified path as the virtual root\n\nARGS:\n  <PATH>            Path to focus on, or enter if directory, (default is `.`)\n  <SELECTION>...    Paths to select, requires <PATH> to be set explicitly",
        VERSION, AUTHOR
    );
}

fn print_version() {
    println!("xplr {}", VERSION);
}

fn validate_message(msg: &str) -> bool {
    // Check if it's a simple message name
    if VALID_MESSAGES.contains(&msg) {
        return true;
    }

    // Check if it's a complex message with parameters
    // Complex messages start with { or contain =
    if msg.starts_with('{') || msg.contains('=') || msg.starts_with('"') {
        return true;
    }

    false
}

fn parse_args() -> Result<Config, String> {
    let mut config = Config::default();
    let args: Vec<String> = env::args().collect();

    let mut i = 1;
    let mut end_options = false;

    while i < args.len() {
        let arg = &args[i];

        if !end_options && arg == "--" {
            end_options = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "-" {
            config.stdin = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "-V" || arg == "--version" {
            config.version = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "-h" || arg == "--help" {
            config.help = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "--force-focus" {
            config.force_focus = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "--print-pwd-as-result" {
            config.print_pwd_as_result = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "--read-only" {
            config.read_only = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "--read0" {
            config.read0 = true;
            i += 1;
            continue;
        }

        if !end_options && arg == "--write0" {
            config.write0 = true;
            i += 1;
            continue;
        }

        if !end_options && (arg == "-0" || arg == "--null") {
            config.null = true;
            config.read0 = true;
            config.write0 = true;
            i += 1;
            continue;
        }

        if !end_options && (arg == "-m" || arg == "--pipe-msg-in") {
            if i + 1 >= args.len() {
                return Err(format!("{} requires a value", arg));
            }
            i += 1;
            config.pipe_msg_in = Some(args[i].clone());
            i += 1;
            continue;
        }

        if !end_options && (arg == "-M" || arg == "--print-msg-in") {
            if i + 1 >= args.len() {
                return Err(format!("{} requires a value", arg));
            }
            i += 1;
            let msg = args[i].clone();
            if !validate_message(&msg) {
                let col = msg.len() + 3;
                return Err(format!("unknown variant `{}`, expected one of `ExplorePwd`, `ExplorePwdAsync`, `ExploreParentsAsync`, `TryCompletePath`, `ClearScreen`, `Refresh`, `FocusNext`, `FocusNextSelection`, `FocusNextByRelativeIndex`, `FocusNextByRelativeIndexFromInput`, `FocusPrevious`, `FocusPreviousSelection`, `FocusPreviousByRelativeIndex`, `FocusPreviousByRelativeIndexFromInput`, `FocusFirst`, `FocusLast`, `FocusPath`, `FocusPathFromInput`, `FocusByIndex`, `FocusByIndexFromInput`, `FocusByFileName`, `ScrollUp`, `ScrollDown`, `ScrollUpHalf`, `ScrollDownHalf`, `ChangeDirectory`, `Enter`, `Back`, `LastVisitedPath`, `NextVisitedPath`, `PreviousVisitedDeepBranch`, `NextVisitedDeepBranch`, `FollowSymlink`, `SetVroot`, `UnsetVroot`, `ToggleVroot`, `ResetVroot`, `SetInputPrompt`, `UpdateInputBuffer`, `UpdateInputBufferFromKey`, `BufferInput`, `BufferInputFromKey`, `SetInputBuffer`, `RemoveInputBufferLastCharacter`, `RemoveInputBufferLastWord`, `ResetInputBuffer`, `SwitchMode`, `SwitchModeKeepingInputBuffer`, `SwitchModeBuiltin`, `SwitchModeBuiltinKeepingInputBuffer`, `SwitchModeCustom`, `SwitchModeCustomKeepingInputBuffer`, `PopMode`, `PopModeKeepingInputBuffer`, `SwitchLayout`, `SwitchLayoutBuiltin`, `SwitchLayoutCustom`, `Call`, `Call0`, `CallSilently`, `CallSilently0`, `BashExec`, `BashExec0`, `BashExecSilently`, `BashExecSilently0`, `CallLua`, `CallLuaSilently`, `LuaEval`, `LuaEvalSilently`, `Select`, `SelectAll`, `SelectPath`, `UnSelect`, `UnSelectAll`, `UnSelectPath`, `ToggleSelection`, `ToggleSelectAll`, `ToggleSelectionByPath`, `ClearSelection`, `AddNodeFilter`, `RemoveNodeFilter`, `ToggleNodeFilter`, `AddNodeFilterFromInput`, `RemoveNodeFilterFromInput`, `RemoveLastNodeFilter`, `ResetNodeFilters`, `ClearNodeFilters`, `AddNodeSorter`, `RemoveNodeSorter`, `ReverseNodeSorter`, `ToggleNodeSorter`, `ReverseNodeSorters`, `RemoveLastNodeSorter`, `ResetNodeSorters`, `ClearNodeSorters`, `Search`, `SearchFromInput`, `SearchFuzzy`, `SearchFuzzyFromInput`, `SearchFuzzyUnordered`, `SearchFuzzyUnorderedFromInput`, `SearchRegex`, `SearchRegexFromInput`, `SearchRegexUnordered`, `SearchRegexUnorderedFromInput`, `ToggleSearchAlgorithm`, `EnableSearchOrder`, `DisableSearchOrder`, `ToggleSearchOrder`, `AcceptSearch`, `CancelSearch`, `EnableMouse`, `DisableMouse`, `ToggleMouse`, `StartFifo`, `StopFifo`, `ToggleFifo`, `LogInfo`, `LogSuccess`, `LogWarning`, `LogError`, `Debug`, `Quit`, `PrintPwdAndQuit`, `PrintFocusPathAndQuit`, `PrintSelectionAndQuit`, `PrintResultAndQuit`, `PrintAppStateAndQuit`, `Terminate` at line 1 column {}", msg, col));
            }
            config.print_msg_in = Some(msg);
            i += 1;
            continue;
        }

        if !end_options && (arg == "-c" || arg == "--config") {
            if i + 1 >= args.len() {
                return Err(format!("{} requires a value", arg));
            }
            i += 1;
            config.config = Some(PathBuf::from(&args[i]));
            i += 1;
            continue;
        }

        if !end_options && (arg == "-C" || arg == "--extra-config") {
            if i + 1 >= args.len() {
                return Err(format!("{} requires a value", arg));
            }
            i += 1;
            config.extra_config.push(PathBuf::from(&args[i]));
            i += 1;
            continue;
        }

        if !end_options && arg == "--on-load" {
            if i + 1 >= args.len() {
                return Err(format!("{} requires a value", arg));
            }
            i += 1;
            config.on_load.push(args[i].clone());
            i += 1;
            continue;
        }

        if !end_options && arg == "--vroot" {
            if i + 1 >= args.len() {
                return Err(format!("{} requires a value", arg));
            }
            i += 1;
            config.vroot = Some(PathBuf::from(&args[i]));
            i += 1;
            continue;
        }

        if !end_options && arg.starts_with('-') {
            eprintln!(
                "error: invalid argument: \"{}\", try `-- \"{}\"` or `--help`",
                arg, arg
            );
            process::exit(1);
        }

        // Positional arguments
        if config.path.is_none() {
            config.path = Some(PathBuf::from(arg));
        } else {
            config.selections.push(PathBuf::from(arg));
        }

        i += 1;
    }

    Ok(config)
}

fn main() {
    let config = match parse_args() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: {}", e);
            process::exit(1);
        }
    };

    // Handle --version
    if config.version {
        print_version();
        return;
    }

    // Handle --help
    if config.help {
        print_help();
        return;
    }

    // Handle --print-msg-in
    if let Some(msg) = config.print_msg_in {
        println!("\"{}\"", msg);
        return;
    }

    // Handle --pipe-msg-in
    if let Some(_msg) = config.pipe_msg_in {
        // This would communicate with the active xplr session
        return;
    }

    // Validate path if provided
    if let Some(ref path) = config.path {
        if !path.exists() {
            eprintln!("error: path doesn't exist: {}", path.display());
            process::exit(1);
        }
    }

    // If --stdin flag is set, read paths from stdin
    if config.stdin {
        let mut buffer = String::new();
        if io::stdin().read_to_string(&mut buffer).is_ok() {
            let separator = if config.read0 { '\0' } else { '\n' };
            for line in buffer.split(separator) {
                let path = PathBuf::from(line);
                if !path.as_os_str().is_empty() && !path.exists() {
                    eprintln!("error: path doesn't exist: {}", path.display());
                    process::exit(1);
                }
            }
        }
        return;
    }

    // Start the TUI
    // For now, this is a stub - just exit successfully
}
